INSERT INTO public.articulos (id, titulo, categoria_id, url, texto, embedding_titulo, embedding_texto, actualizado) VALUES (
    1003,
    'Cómo emitir una nota de crédito vinculada a una factura de venta',
    10,
    'https://conocimiento.ejemplo.local/t/emitir-nota-credito-vinculada-factura/1003',
    '# Consulta
Se requiere anular parcial o totalmente una factura ya emitida mediante una nota de crédito referenciada.

# Pasos a seguir
1. Dirigirse a Ventas > Comprobantes > Notas de Crédito.
2. Seleccionar el cliente y utilizar la acción Aplicar Comprobante Origen.
3. Marcar la factura correspondiente e indicar las cantidades o importes a devolver.
4. Confirmar si el movimiento reingresa mercadería al depósito.
5. Guardar y emitir el comprobante electrónico.',
