INSERT INTO public.articulos (id, titulo, categoria_id, url, texto, embedding_titulo, embedding_texto, actualizado) VALUES (
    1006,
    'Cómo registrar una orden de compra a partir de solicitudes aprobadas',
    20,
    'https://conocimiento.ejemplo.local/t/registrar-orden-compra-solicitudes-aprobadas/1006',
    '# Consulta
Se necesita consolidar varias solicitudes internas de abastecimiento en una orden de compra formal para el proveedor.

# Pasos a seguir
1. Abrir el módulo Compras > Bandeja de Solicitudes Aprobadas.
2. Seleccionar los ítems pendientes de compra y presionar Generar Orden.
3. Completar el proveedor adjudicado, la condición de pago y el plazo de entrega.
4. Guardar la orden de compra para enviarla al circuito de autorización.',
