INSERT INTO public.articulos (id, titulo, categoria_id, url, texto, embedding_titulo, embedding_texto, actualizado) VALUES (
    1007,
    'Bloqueo al ingresar factura de proveedor por desvío en tolerancia de precio',
    20,
    'https://conocimiento.ejemplo.local/t/bloqueo-factura-proveedor-tolerancia-precio/1007',
    '# Causa
El precio unitario informado en el comprobante del proveedor supera el porcentaje máximo de desvío admitido respecto de la orden de compra.

# Solución
1. Verificar si corresponde actualizar el precio pactado en la orden de compra original.
2. En caso de tratarse de una diferencia aceptada, solicitar la liberación del comprobante desde Compras > Autorizaciones por Desvío.
3. Una vez liberado, contabilizar el comprobante en cuentas a pagar.',
