INSERT INTO public.articulos (id, titulo, categoria_id, url, texto, embedding_titulo, embedding_texto, actualizado) VALUES (
    1008,
    'Cómo cargar un remito de recepción de mercadería asociado a orden de compra',
    20,
    'https://conocimiento.ejemplo.local/t/cargar-remito-recepcion-mercaderia-orden-compra/1008',
    '# Consulta
Se requiere dar ingreso físico al depósito a los productos entregados por un proveedor vinculando la orden de compra.

# Pasos a seguir
1. Ingresar a Inventario > Recepciones > Nuevo Remito de Compra.
2. Seleccionar el proveedor y vincular el número de orden de compra pendiente.
3. Informar el depósito de destino y las cantidades efectivamente recibidas.
4. Confirmar el movimiento para actualizar el stock disponible.',
