INSERT INTO public.articulos (id, titulo, categoria_id, url, texto, embedding_titulo, embedding_texto, actualizado) VALUES (
    1010,
    'Asiento contable desbalanceado al contabilizar liquidación de impuestos',
    30,
    'https://conocimiento.ejemplo.local/t/asiento-contable-desbalanceado-liquidacion-impuestos/1010',
    '# Causa
Uno de los conceptos fiscales incluidos en la liquidación no posee cuenta contable de contrapartida asignada en la matriz de contabilización.

# Solución
1. Ingresar a Contabilidad > Configuración > Matriz de Cuentas por Concepto.
2. Identificar el concepto impositivo sin cuenta y asociar la cuenta de pasivo correspondiente.
3. Regenerar la minuta contable de la liquidación y confirmar el asiento.',
