INSERT INTO public.articulos (id, titulo, categoria_id, url, texto, embedding_titulo, embedding_texto, actualizado) VALUES (
    1014,
    'Cómo registrar una transferencia de stock entre depósitos de distintas sucursales',
    40,
    'https://conocimiento.ejemplo.local/t/registrar-transferencia-stock-entre-depositos/1014',
    '# Consulta
Se requiere trasladar mercadería desde el depósito central hacia una sucursal dejando trazabilidad del tránsito.

# Pasos a seguir
1. Ingresar a Inventario > Movimientos > Transferencia entre Depósitos.
2. Seleccionar el depósito de origen, el depósito en tránsito y el depósito de destino.
3. Detallar los artículos, lotes y cantidades a enviar.
4. Emitir el remito interno de salida y, al arribar la mercadería, confirmar la recepción en destino.',
