INSERT INTO public.articulos (id, titulo, categoria_id, url, texto, embedding_titulo, embedding_texto, actualizado) VALUES (
    1016,
    'Cómo realizar una toma de inventario físico y generar ajustes por diferencia',
    40,
    'https://conocimiento.ejemplo.local/t/realizar-toma-inventario-fisico-ajustes/1016',
    '# Consulta
Se desea relevar el conteo físico de un depósito y registrar automáticamente las altas o bajas por diferencias de inventario.

# Pasos a seguir
1. Crear un corte de conteo en Inventario > Recuento Físico > Nueva Toma.
2. Imprimir o exportar las planillas ciegas por ubicación y cargar las cantidades contadas.
3. Analizar el informe comparativo entre saldo teórico y saldo relevado.
4. Aprobar la toma para que el sistema genere el comprobante de ajuste de stock y su asiento contable.',
