INSERT INTO public.articulos (id, titulo, categoria_id, url, texto, embedding_titulo, embedding_texto, actualizado) VALUES (
    1017,
    'Cómo configurar el método de valuación a costo promedio ponderado',
    40,
    'https://conocimiento.ejemplo.local/t/configurar-valuacion-costo-promedio-ponderado/1017',
    '# Consulta
Se necesita parametrizar el cálculo automático del costo promedio ponderado para valorizar las salidas de inventario.

# Pasos a seguir
1. Acceder a Configuración > Inventario > Métodos de Costeo.
2. Seleccionar Costo Promedio Ponderado como criterio predeterminado de la familia de artículos.
3. Definir la cuenta contable de costo de mercadería vendida.
4. Programar el proceso nocturno de recálculo cronológico de costos.',
