INSERT INTO public.articulos (id, titulo, categoria_id, url, texto, embedding_titulo, embedding_texto, actualizado) VALUES (
    1019,
    'Cómo importar extractos bancarios y ejecutar la conciliación automática',
    50,
    'https://conocimiento.ejemplo.local/t/importar-extractos-bancarios-conciliacion-automatica/1019',
    '# Consulta
Se requiere conciliar los movimientos del libro banco contra el archivo electrónico descargado de la entidad bancaria.

# Pasos a seguir
1. Ingresar a Tesorería > Bancos > Importación de Extractos.
2. Seleccionar la cuenta bancaria, la plantilla de formato y el archivo del período.
3. Ejecutar el motor de conciliación automática por importe, fecha y número de cheque o referencia.
4. Revisar las partidas pendientes y confirmar la conciliación bancaria.',
