INSERT INTO public.articulos (id, titulo, categoria_id, url, texto, embedding_titulo, embedding_texto, actualizado) VALUES (
    1020,
    'Cómo registrar el rechazo de un cheque de terceros depositado',
    50,
    'https://conocimiento.ejemplo.local/t/registrar-rechazo-cheque-terceros-depositado/1020',
    '# Consulta
Un cheque recibido de un cliente y depositado en el banco fue rechazado y debe revertirse el cobro generando el cargo correspondiente.

# Pasos a seguir
1. Ir a Tesorería > Cartera de Cheques > Gestión de Rechazos.
2. Buscar el cheque en estado Depositado y ejecutar la acción Marcar como Rechazado.
3. Informar la fecha del débito bancario y los gastos de comisión.
4. Tildar Generar Nota de Débito al Cliente para recomponer el saldo en cuenta corriente.',
