INSERT INTO public.articulos (id, titulo, categoria_id, url, texto, embedding_titulo, embedding_texto, actualizado) VALUES (
    1021,
    'Error al emitir orden de pago con retención de ganancias por mínimo no imponible',
    50,
    'https://conocimiento.ejemplo.local/t/error-orden-pago-retencion-ganancias-minimo/1021',
    '# Causa
La tabla de escalas y mínimos no imponibles del régimen de retención no tiene vigencia activa para el mes de la orden de pago.

# Solución
1. Abrir Impuestos > Retenciones > Regímenes y Escalas.
2. Seleccionar el régimen correspondiente y agregar una fila de vigencia que cubra la fecha actual.
3. Volver a calcular las retenciones dentro de la orden de pago antes de emitirla.',
