INSERT INTO public.articulos (id, titulo, categoria_id, url, texto, embedding_titulo, embedding_texto, actualizado) VALUES (
    1025,
    'El programador de tareas automáticas no ejecuta el respaldo nocturno',
    60,
    'https://conocimiento.ejemplo.local/t/programador-tareas-no-ejecuta-respaldo-nocturno/1025',
    '# Causa
El servicio de ejecución en segundo plano se detuvo tras un reinicio del servidor o carece de permisos de escritura en la carpeta de destino.

# Solución
1. Verificar en el monitor de servicios que el agente de tareas programadas esté en estado Iniciado con inicio automático.
2. Comprobar que la cuenta de servicio tenga permisos de lectura y escritura sobre el directorio de copias de seguridad.
3. Ejecutar una prueba manual desde Configuración > Tareas Programadas.',
