INSERT INTO public.articulos (id, titulo, categoria_id, url, texto, embedding_titulo, embedding_texto, actualizado) VALUES (
    1026,
    'Cómo configurar el envío de comprobantes por correo mediante servidor SMTP',
    60,
    'https://conocimiento.ejemplo.local/t/configurar-envio-comprobantes-servidor-smtp/1026',
    '# Consulta
Se necesita parametrizar la casilla de salida para que las facturas y órdenes de compra se envíen en PDF de forma automática.

# Pasos a seguir
1. Abrir Configuración > Comunicaciones > Parámetros de Correo.
2. Completar la dirección del servidor SMTP, el puerto y el protocolo de cifrado TLS.
3. Ingresar las credenciales de autenticación mediante variable de entorno o bóveda segura.
4. Presionar Enviar Correo de Prueba y guardar la configuración.',
