INSERT INTO public.articulos (id, titulo, categoria_id, url, texto, embedding_titulo, embedding_texto, actualizado) VALUES (
    1027,
    'Cómo auditar el historial de modificaciones de un registro maestro',
    60,
    'https://conocimiento.ejemplo.local/t/auditar-historial-modificaciones-registro-maestro/1027',
    '# Consulta
Se requiere consultar qué usuario modificó un campo sensible en el maestro de artículos o proveedores y en qué fecha ocurrió.

# Pasos a seguir
1. Ingresar a Configuración > Auditoría > Visor de Cambios.
2. Filtrar por la entidad deseada, el identificador del registro y el rango de fechas.
3. Inspeccionar el detalle comparativo entre el valor anterior y el valor nuevo de cada atributo.',
