INSERT INTO public.articulos (id, titulo, categoria_id, url, texto, embedding_titulo, embedding_texto, actualizado) VALUES (
    1030,
    'Cómo parametrizar centros de costos y reglas de distribución contable',
    30,
    'https://conocimiento.ejemplo.local/t/parametrizar-centros-costos-distribucion-contable/1030',
    '# Consulta
Se necesita distribuir automáticamente los gastos generales entre las distintas áreas operativas al registrar comprobantes de compra.

# Pasos a seguir
1. Dar de alta las unidades de análisis en Contabilidad > Centros de Costos.
2. Definir una base de prorrateo porcentual en Reglas de Distribución.
3. Vincular la regla a las cuentas contables de gastos de estructura.
4. Verificar la apertura por centro de costos al emitir el balance de sumas y saldos.',
