INSERT INTO public.articulos (id, titulo, categoria_id, url, texto, embedding_titulo, embedding_texto, actualizado) VALUES (
    1031,
    'Novedades versión ERP 2024',
    70,
    'https://conocimiento.ejemplo.local/t/novedades-version-erp-2024/1031',
    '# Consulta
Resumen de mejoras funcionales incorporadas en la actualización anual 2024 del sistema de gestión.

# Pasos a seguir
1. Revisar el nuevo panel de conciliación bancaria asistida en el módulo de Tesorería.
2. Habilitar la validación anticipada de padrones impositivos desde Configuración Fiscal.
3. Consultar la guía de actualización de esquemas antes de iniciar el despliegue.',
