INSERT INTO public.articulos (id, titulo, categoria_id, url, texto, embedding_titulo, embedding_texto, actualizado) VALUES (
    1032,
    'Novedades versión ERP 2025',
    70,
    'https://conocimiento.ejemplo.local/t/novedades-version-erp-2025/1032',
    '# Consulta
Resumen de mejoras funcionales y optimizaciones de rendimiento incluidas en la versión 2025 del sistema de gestión.

# Pasos a seguir
1. Activar el motor de búsqueda semántica de artículos en la base de conocimiento.
2. Configurar las nuevas reglas de autorización multinivel para órdenes de compra.
3. Verificar la compatibilidad de los reportes personalizados tras aplicar el paquete.',
